//SOUND_BEGIN
// =========================================================================
// Title: Alps (Wind Audio)
// Author: David Hoskins
// Source: https://www.shadertoy.com/view/4ssXW2
// License: CC BY-NC-SA 3.0 (Creative Commons Attribution-NonCommercial-ShareAlike 3.0)
//
// Note: Adapted for Desktop GLSL Audio. The original texture-based 
//       hash (iChannel0) has been replaced with a math-based pseudo-random hash.
// =========================================================================

// Mathematical Hash to replace the original textureLod(iChannel0)
vec2 Hash(vec2 p) 
{
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(p) * 43758.5453123);
}

//--------------------------------------------------------------------------
vec2 Noise( in vec2 x )
{
    vec2 p = floor(x);
    vec2 f = fract(x);
    f = f*f*(3.0 - 2.0*f);
    vec2 res = mix(mix( Hash(p + 0.0), Hash(p + vec2(1.0, 0.0)), f.x),
                   mix( Hash(p + vec2(0.0, 1.0)), Hash(p + vec2(1.0, 1.0)), f.x), f.y);
    return res - 0.5;
}

//--------------------------------------------------------------------------
vec2 FBM( vec2 p )
{
    vec2 f;
    f  = 0.5000  * Noise(p); p = p * 2.32;
    f += 0.2500  * Noise(p); p = p * 2.23;
    f += 0.1250  * Noise(p); p = p * 2.31;
    f += 0.0625  * Noise(p); p = p * 2.28;
    f += 0.03125 * Noise(p);
    return f;
}

//--------------------------------------------------------------------------
vec2 Wind(float n)
{
    vec2 pos = vec2(n * 162.017331, n * 132.066927);
    vec2 vol = Noise(vec2(n * 23.131, -n * 42.13254)) * 1.0 + 1.0;

    vec2 noise = vec2(FBM(pos * 33.313)) * vol.x * 0.5 + vec2(FBM(pos * 4.519)) * vol.y;

    return noise;
}

//--------------------------------------------------------------------------
vec2 mainSound( int samp, float time )
{
    vec2 audio = Wind(time * 0.1) * 6.0;

    // Envelope: fades in (0-2 sec) and out (175-180 sec)
    return clamp(audio, -1.0, 1.0) * (smoothstep(0.0, 2.0, time) * smoothstep(180.0, 175.0, time));
}
//SOUND_END

// =========================================================================
// Title: Disco Sun Vortex
// Author: workingclasshacker (@WorkingClassHacker)
// Source: https://www.shadertoy.com/view/7cfGzn
//
// License: SPDX-License-Identifier: CC-BY-NC-SA-4.0
//          https://creativecommons.org/licenses/by-nc-sa/4.0/
//          Copyright (c) 2026 @WorkingClassHacker
//
// Attributions & Credits:
// - Based on "Abstract Shine" by @Frostbyte (Copyright (c) 2026)
// - Continuous cosine palette by Inigo Quilez / IQ (MIT License) 
//   https://www.shadertoy.com/view/ll2GD3
//
// Description:
// Volumetric raymarching shader featuring organic deformation fields, 
// depth-dependent coloration using continuous cosine palettes, and 
// time-gated screen-space shimmer.
// =========================================================================
// Rotation matrix using cosine phase offsets.
// cos(a+33) ≈ -sin(a)
// cos(a+11) ≈  sin(a)
// compact 2D rotation without sin(). 
// Approximates sin within an invisible margin for animated graphics

#define R(a) mat2(cos(a+vec4(0, 33, 11, 0)))

// IQ`s continuous cosine palette (MIT)
// produces smooth, periodic color gradients
// https://www.shadertoy.com/view/ll2GD3

vec3 palette(float i){
    const vec3 a = vec3(0.50, 0.38, 0.26);  // base tone (warm midtone)
    const vec3 b = vec3(0.50, 0.35, 0.25);  // amplitude (vibrance)
    const vec3 c = vec3(1.00);              // frequency (cyclic complexity)
    const vec3 d = vec3(0.00, 0.12, 0.25);  // phase offsets (hue shift)
    return a + b * cos(6.2831853 * (c * i + d));
}

vec3 palette2(float i){
    // Rimosse tutte le "f" finali per compatibilità universale
    const vec3 a = vec3(0.742702, 0.908877, 0.959831);
    const vec3 b = vec3(-0.711000, 0.275000, -0.052000);
    const vec3 c = vec3(1.000000, 1.855000, 1.000000);
    const vec3 d = vec3(0.180000, 0.091000, 0.380000);
    return a + b * cos(6.2831853 * (c * i + d));
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // pixel coordinate
    vec2 u = fragCoord.xy;

    // normalized screen space
    vec2 uv = (u - 0.5*iResolution.xy + 0.5) / iResolution.y;

    // FIX 1: Inizializziamo a zero!
    float i = 0.0;
    float s = 0.0;
    float t = iTime;

    // FIX 2: Inizializziamo p a zero, poi impostiamo la Z
    vec3 p = vec3(0.0, 0.0, t);

    // ray direction
    vec3 d = normalize(vec3(
        2.0 * u - iResolution.xy,
        iResolution.y
    ));

    // FIX 3: Inizializziamo il colore a nero prima di sommarci la luce
    fragColor = vec4(0.0);

    // raymarch loop (ciclo pulito e standard)
    for (i = 0.0; i < 20.0; i++)
    {
        // depth-dependent rotation
        p.xy *= R(-p.z * 0.01 - iTime * 0.05);

        // base step size
        s = 0.6;

        // cylindrical confinement
        s = max(s, 4.0 * (-length(p.xy) + 10.0));

        // organic deformation field
        s += abs(
            p.y * 0.004 +                
            sin(t - p.x * 0.5) * 0.9 +  
            1.0                          
        );

        // march ray forward
        p += d * s;

        // volumetric glow accumulation
        fragColor += 1.0 / (s * 0.2);
    }

    // apply palette 
    fragColor *= vec4(palette(length(p)/(abs(sin(iTime*0.02)*50.)+6.0)), 1.0);

    // time-gated screen-space shimmer 
    fragColor -= 20.0 *
        smoothstep(
            .001,
            abs(sin(iTime*5.0)), 
            .7 - length(sin(uv*200.0)/1.5)-abs(uv.y)+.2   
        );

    // brightness normalization
    fragColor /= 0.5e2;

    // radial gradient
    float l = length(uv);

    // vignette
    fragColor *= 1.2-l;

    // center glow
    fragColor = mix(fragColor, palette(l-.23).rgbr, 1.0-smoothstep(.01,.95,l));

    // soft highlight compression
    fragColor = tanh(fragColor+fragColor);
}

